#!/usr/bin/env python3
"""calcul_12.py – Calcul de 6 + 6 et affichage du résultat."""

def addition(a: int, b: int) -> int:
    """Retourne la somme de a et b."""
    return a + b


if __name__ == "__main__":
    try:
